{"content":"import { MoreVertical } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Form, FormDrawer, Textarea } from '@/components/ui/form';
import { useNotifications } from '@/components/ui/notifications';

import {
  updateCommentInputSchema,
  useUpdateComment,
} from '../api/update-comment';

type UpdateCommentProps = {
  id: string;
  discussionId: string;
  currentBody: string;
};

export const UpdateComment = ({
  id,
  discussionId,
  currentBody,
}: UpdateCommentProps) => {
  const { addNotification } = useNotifications();
  const updateCommentMutation = useUpdateComment({
    discussionId,
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'Comment Updated',
        });
      },
    },
  });

  return (
    <FormDrawer
      isDone={updateCommentMutation.isSuccess}
      triggerButton={
        <Button variant="ghost" size="sm" icon={<MoreVertical className="size-4" />}>
          Edit
        </Button>
      }
      title="Update Comment"
      submitButton={
        <Button
          isLoading={updateCommentMutation.isPending}
          form="update-comment"
          type="submit"
          size="sm"
          disabled={updateCommentMutation.isPending}
        >
          Submit
        </Button>
      }
    >
      <Form
        id="update-comment"
        onSubmit={(values) => {
          updateCommentMutation.mutate({
            commentId: id,
            data: values,
          });
        }}
        schema={updateCommentInputSchema}
        options={{
          defaultValues: {
            body: currentBody,
          },
        }}
      >
